INSERT INTO public.recipes
  (slug, title, category, description, calories, protein_g, carbs_g, fat_g, servings, prep_minutes, tags, ingredients, steps, source)
VALUES
('ares-pb-banana-protein-oats', 'Peanut Butter Banana Protein Oats', 'Breakfast', 'Creamy oats with whey, banana and a swirl of peanut butter — a big protein breakfast.', 620, 40, 80, 16, 1, 8, ARRAY['high-protein','quick','vegetarian']::text[], ARRAY['60g rolled oats','250ml milk','1 scoop vanilla whey','1 banana','1 tbsp peanut butter','Cinnamon to taste']::text[], ARRAY['Cook the oats with the milk until creamy.','Stir in the whey off the heat with a splash more milk.','Top with sliced banana, peanut butter and cinnamon.']::text[], 'seed'),
('ares-greek-yogurt-granola-bowl', 'Greek Yoghurt Granola & Berry Bowl', 'Breakfast', 'Thick Greek yoghurt with whey, granola and berries for an easy high-protein start.', 450, 38, 45, 10, 1, 5, ARRAY['high-protein','quick','vegetarian','no-cook']::text[], ARRAY['200g Greek yoghurt','1/2 scoop whey','40g granola','100g mixed berries','1 tsp honey']::text[], ARRAY['Stir the whey through the yoghurt.','Top with granola, berries and a drizzle of honey.']::text[], 'seed'),
('ares-veggie-cheese-omelette', 'Three-Egg Veggie & Cheese Omelette', 'Breakfast', 'A fluffy omelette loaded with peppers, spinach and cheese.', 480, 30, 12, 34, 1, 10, ARRAY['high-protein','low-carb','vegetarian']::text[], ARRAY['3 eggs','30g grated cheese','Handful of spinach','1/2 pepper, diced','1 tsp olive oil','Salt and pepper']::text[], ARRAY['Whisk the eggs with salt and pepper.','Soften the pepper and spinach in the oil.','Pour in the eggs, add cheese, fold and cook through.']::text[], 'seed'),
('ares-berry-protein-pancakes', 'Berry Protein Pancakes', 'Breakfast', 'Light protein pancakes topped with berries and yoghurt.', 520, 40, 60, 10, 1, 12, ARRAY['high-protein','vegetarian']::text[], ARRAY['1 scoop whey','1 egg','1 banana','40g oat flour','100g Greek yoghurt','Handful of berries']::text[], ARRAY['Blend the whey, egg, banana and oat flour into a batter.','Cook small pancakes in a non-stick pan.','Top with yoghurt and berries.']::text[], 'seed'),
('ares-avocado-eggs-toast', 'Avocado & Eggs on Sourdough', 'Breakfast', 'Smashed avocado and poached eggs on toasted sourdough.', 520, 26, 38, 28, 1, 10, ARRAY['vegetarian']::text[], ARRAY['2 eggs','1/2 avocado','1 slice sourdough','Chilli flakes','Lemon juice','Salt and pepper']::text[], ARRAY['Toast the sourdough and smash the avocado on top with lemon and salt.','Poach or fry the eggs and set them on the avocado.','Finish with chilli flakes and pepper.']::text[], 'seed'),
('ares-berry-overnight-oats', 'Berry Overnight Oats', 'Breakfast', 'Prep-ahead oats soaked with yoghurt and berries.', 430, 28, 55, 10, 1, 5, ARRAY['make-ahead','vegetarian','no-cook']::text[], ARRAY['50g rolled oats','150g Greek yoghurt','100ml milk','1/2 scoop whey','100g berries','1 tsp chia seeds']::text[], ARRAY['Mix the oats, yoghurt, milk, whey and chia in a jar.','Chill overnight.','Top with berries in the morning.']::text[], 'seed'),
('ares-tofu-scramble-toast', 'Tofu Scramble on Toast', 'Vegan', 'Turmeric tofu scramble with spinach on wholegrain toast.', 420, 28, 35, 20, 1, 12, ARRAY['vegan','dairy-free','high-protein']::text[], ARRAY['200g firm tofu','1 slice wholegrain bread','Handful of spinach','1/4 tsp turmeric','1 tsp olive oil','Salt and pepper']::text[], ARRAY['Crumble the tofu and fry in the oil with turmeric.','Wilt the spinach through.','Serve on toasted wholegrain bread.']::text[], 'seed'),
('ares-whey-oat-smoothie', 'Whey, Oat & Banana Smoothie', 'Breakfast', 'A drinkable breakfast — blend and go.', 450, 35, 55, 8, 1, 3, ARRAY['quick','high-protein','vegetarian','no-cook']::text[], ARRAY['1 scoop whey','1 banana','40g oats','300ml milk','Handful of ice']::text[], ARRAY['Blend everything until smooth.']::text[], 'seed'),
('ares-egg-white-spinach-scramble', 'Egg-White & Spinach Scramble', 'Breakfast', 'A lean, high-protein scramble with a slice of toast.', 300, 30, 25, 8, 1, 8, ARRAY['cutting','high-protein','low-fat']::text[], ARRAY['4 egg whites','1 whole egg','Handful of spinach','1 slice wholegrain toast','Salt and pepper']::text[], ARRAY['Scramble the eggs and whites with the spinach.','Serve with a slice of wholegrain toast.']::text[], 'seed'),
('ares-skyr-seed-bowl', 'Skyr, Berry & Seed Bowl', 'Breakfast', 'High-protein skyr with berries and a little granola.', 300, 30, 35, 4, 1, 4, ARRAY['cutting','high-protein','low-fat','no-cook']::text[], ARRAY['200g skyr','100g berries','20g granola','1 tsp mixed seeds']::text[], ARRAY['Top the skyr with berries, granola and seeds.']::text[], 'seed'),
('ares-chicken-rice-bowl', 'Grilled Chicken & Rice Bowl', 'Chicken', 'Grilled chicken over rice with vegetables and a drizzle of olive oil.', 700, 55, 80, 18, 1, 20, ARRAY['high-protein','meal-prep']::text[], ARRAY['200g chicken breast','1.5 cups cooked rice','1 cup mixed vegetables','1 tbsp olive oil','Garlic and paprika','Salt and pepper']::text[], ARRAY['Season and grill the chicken, then slice.','Warm the rice and vegetables.','Combine in a bowl and finish with olive oil.']::text[], 'seed'),
('ares-chicken-salad-wrap', 'Chicken Salad Wholegrain Wrap', 'Chicken', 'Sliced chicken and crunchy salad in a wholegrain wrap.', 560, 45, 45, 18, 1, 10, ARRAY['high-protein','quick']::text[], ARRAY['180g cooked chicken','1 wholegrain wrap','Lettuce, tomato and cucumber','1 tbsp light mayo','Salt and pepper']::text[], ARRAY['Fill the wrap with chicken and salad.','Add the mayo, season and roll up.']::text[], 'seed'),
('ares-chicken-quinoa-bowl', 'Chicken & Quinoa Veg Bowl', 'Chicken', 'Chicken with quinoa and roasted vegetables.', 600, 48, 55, 16, 1, 20, ARRAY['high-protein','meal-prep']::text[], ARRAY['180g chicken breast','3/4 cup cooked quinoa','1 cup roasted vegetables','1 tsp olive oil','Lemon and herbs']::text[], ARRAY['Roast the vegetables and cook the quinoa.','Grill and slice the chicken.','Toss together with lemon, herbs and olive oil.']::text[], 'seed'),
('ares-chicken-fajitas', 'Chicken Fajitas', 'Chicken', 'Spiced chicken with peppers and onions in soft tortillas.', 640, 45, 60, 20, 1, 20, ARRAY['high-protein']::text[], ARRAY['180g chicken breast','2 small tortillas','1 pepper','1/2 onion','Fajita spice','1 tsp olive oil']::text[], ARRAY['Sear the spiced chicken strips in the oil.','Add the peppers and onion until soft.','Serve in warm tortillas.']::text[], 'seed'),
('ares-roast-chicken-potatoes', 'Roast Chicken, Potatoes & Veg', 'Chicken', 'A classic roast plate of chicken, potatoes and greens.', 700, 52, 55, 26, 1, 35, ARRAY['high-protein']::text[], ARRAY['200g chicken','200g potatoes','1 cup greens','1 tbsp olive oil','Rosemary','Salt and pepper']::text[], ARRAY['Roast the potatoes and chicken with oil and rosemary.','Steam the greens.','Plate together.']::text[], 'seed'),
('ares-chicken-caesar', 'Lighter Chicken Caesar Salad', 'Chicken', 'Grilled chicken over crisp cos with a lighter Caesar dressing and croutons.', 520, 45, 25, 26, 1, 12, ARRAY['high-protein','low-carb']::text[], ARRAY['180g chicken breast','1 cos lettuce','20g parmesan','2 tbsp light Caesar dressing','Small handful of croutons']::text[], ARRAY['Grill and slice the chicken.','Toss the cos with dressing, parmesan and croutons.','Top with the chicken.']::text[], 'seed'),
('ares-beef-noodle-stirfry', 'Beef & Veg Noodle Stir-Fry', 'Beef', 'Strips of beef and vegetables tossed with noodles and soy.', 700, 50, 75, 24, 1, 20, ARRAY['high-protein']::text[], ARRAY['180g lean beef strips','1 nest of noodles','2 cups stir-fry vegetables','2 tbsp soy sauce','1 tsp sesame oil','Garlic and ginger']::text[], ARRAY['Sear the beef and set aside.','Stir-fry the vegetables, then add noodles and sauce.','Return the beef and toss through.']::text[], 'seed'),
('ares-beef-burrito-bowl', 'Beef Burrito Bowl', 'Beef', 'Seasoned beef mince with rice, beans, corn and salsa.', 720, 50, 80, 22, 1, 20, ARRAY['high-protein','meal-prep']::text[], ARRAY['180g lean beef mince','1 cup cooked rice','1/2 cup black beans','1/4 cup corn','2 tbsp salsa','Taco seasoning']::text[], ARRAY['Brown the mince with the seasoning.','Build a bowl with rice, beans and corn.','Top with the beef and salsa.']::text[], 'seed'),
('ares-beef-chilli-rice', 'Lean Beef Chilli with Rice', 'Beef', 'A hearty lean beef chilli served over rice.', 640, 45, 60, 20, 1, 30, ARRAY['high-protein','meal-prep']::text[], ARRAY['180g lean beef mince','1/2 cup kidney beans','1/2 tin chopped tomatoes','1 cup cooked rice','Chilli and cumin','1/2 onion']::text[], ARRAY['Brown the mince with onion and spices.','Add tomatoes and beans and simmer.','Serve over rice.']::text[], 'seed'),
('ares-beef-mince-tacos', 'Beef Mince Tacos', 'Beef', 'Soft tacos with seasoned beef, salad and salsa.', 680, 46, 65, 24, 1, 20, ARRAY['high-protein']::text[], ARRAY['180g lean beef mince','3 small taco tortillas','Shredded lettuce','2 tbsp salsa','Taco seasoning','20g cheese']::text[], ARRAY['Cook the seasoned mince.','Fill the tortillas with beef, lettuce, salsa and cheese.']::text[], 'seed'),
('ares-baked-salmon-potatoes', 'Baked Salmon, Potatoes & Greens', 'Seafood', 'Oven-baked salmon with baby potatoes and greens.', 640, 42, 45, 28, 1, 25, ARRAY['high-protein','omega-3']::text[], ARRAY['180g salmon fillet','200g baby potatoes','1 cup greens','1 tbsp olive oil','Lemon','Salt and pepper']::text[], ARRAY['Roast the potatoes with oil.','Bake the salmon with lemon for 12–15 minutes.','Steam the greens and plate together.']::text[], 'seed'),
('ares-salmon-poke-bowl', 'Salmon Poke Bowl', 'Seafood', 'Rice bowl with salmon, edamame, cucumber and a soy-sesame drizzle.', 680, 44, 70, 22, 1, 15, ARRAY['high-protein','omega-3']::text[], ARRAY['160g salmon','1 cup cooked rice','1/2 cup edamame','1/2 cucumber','1 tbsp soy sauce','1 tsp sesame oil']::text[], ARRAY['Cube the salmon (cooked or sashimi-grade).','Build a bowl with rice, edamame and cucumber.','Add the salmon and the soy-sesame drizzle.']::text[], 'seed'),
('ares-tuna-pasta-salad', 'Tuna Pasta Salad', 'Seafood', 'Cold pasta with tuna, sweetcorn and a light dressing.', 620, 42, 70, 16, 1, 15, ARRAY['high-protein','budget','meal-prep']::text[], ARRAY['100g pasta (dry)','1 tin tuna in springwater','1/4 cup sweetcorn','Cherry tomatoes','1 tbsp light mayo','Salt and pepper']::text[], ARRAY['Cook and cool the pasta.','Fold through the tuna, corn, tomatoes and mayo.']::text[], 'seed'),
('ares-white-fish-sweet-potato', 'White Fish, Greens & Sweet Potato', 'Seafood', 'Lean baked white fish with sweet potato and greens.', 500, 45, 40, 15, 1, 25, ARRAY['cutting','high-protein','low-fat']::text[], ARRAY['200g white fish fillet','1 small sweet potato','1 cup greens','1 tsp olive oil','Lemon and herbs']::text[], ARRAY['Roast the sweet potato.','Bake the fish with lemon and herbs.','Steam the greens and plate.']::text[], 'seed'),
('ares-prawn-noodle-stirfry', 'Prawn & Veg Noodle Stir-Fry', 'Seafood', 'Quick prawn stir-fry with vegetables and noodles.', 540, 38, 60, 14, 1, 15, ARRAY['high-protein','quick']::text[], ARRAY['150g prawns','1 nest of noodles','2 cups stir-fry vegetables','2 tbsp soy sauce','1 tsp sesame oil','Garlic and ginger']::text[], ARRAY['Stir-fry the prawns with garlic and ginger.','Add vegetables and noodles with the sauce.','Toss and serve.']::text[], 'seed'),
('ares-tuna-salad-bowl', 'Tuna Salad Bowl', 'Seafood', 'A big lean salad topped with tuna and a light dressing.', 360, 40, 15, 12, 1, 8, ARRAY['cutting','high-protein','low-carb','no-cook']::text[], ARRAY['2 tins tuna in springwater','Large mixed salad','Cherry tomatoes','1 tbsp light vinaigrette','Salt and pepper']::text[], ARRAY['Pile the salad into a bowl.','Top with the tuna and dress lightly.']::text[], 'seed'),
('ares-pork-sweet-potato-mash', 'Pork Chops & Sweet Potato Mash', 'Pork', 'Pan-seared pork chops with sweet potato mash and greens.', 700, 48, 55, 30, 1, 25, ARRAY['high-protein']::text[], ARRAY['2 lean pork chops','1 sweet potato','1 cup greens','1 tsp olive oil','Garlic','Salt and pepper']::text[], ARRAY['Boil and mash the sweet potato.','Sear the pork chops in the oil.','Serve with the mash and steamed greens.']::text[], 'seed'),
('ares-lentil-chickpea-bowl', 'Lentil & Chickpea Feta Bowl', 'Vegetarian', 'A hearty bowl of lentils, chickpeas, salad and feta.', 600, 30, 70, 22, 1, 15, ARRAY['vegetarian','high-fibre','meal-prep']::text[], ARRAY['1 cup cooked lentils','1/2 cup chickpeas','40g feta','Cucumber and tomato','1 tbsp olive oil','Lemon']::text[], ARRAY['Combine the lentils, chickpeas and chopped salad.','Crumble over the feta.','Dress with olive oil and lemon.']::text[], 'seed'),
('ares-halloumi-quinoa-plate', 'Halloumi & Quinoa Veg Plate', 'Vegetarian', 'Pan-fried halloumi with quinoa and roasted vegetables.', 600, 35, 55, 28, 1, 20, ARRAY['vegetarian','high-protein']::text[], ARRAY['120g halloumi','3/4 cup cooked quinoa','1 cup roasted vegetables','1 tsp olive oil','Lemon']::text[], ARRAY['Roast the vegetables and cook the quinoa.','Pan-fry the halloumi until golden.','Plate together with a squeeze of lemon.']::text[], 'seed'),
('ares-tofu-buddha-bowl', 'Tofu Buddha Bowl', 'Vegan', 'Baked tofu with rice, roasted veg and a tahini drizzle.', 560, 28, 65, 18, 1, 20, ARRAY['vegan','dairy-free','high-fibre']::text[], ARRAY['150g firm tofu','3/4 cup cooked rice','1 cup roasted vegetables','1 tbsp tahini','Soy sauce','1 tsp olive oil']::text[], ARRAY['Bake the tofu until firm.','Build a bowl with rice and roasted veg.','Add tofu and a tahini-soy drizzle.']::text[], 'seed'),
('ares-paneer-curry-rice', 'Paneer Curry with Rice', 'Vegetarian', 'A mild tomato paneer curry served with rice.', 640, 32, 70, 26, 1, 25, ARRAY['vegetarian','high-protein']::text[], ARRAY['120g paneer','1 cup cooked rice','1/2 tin chopped tomatoes','Curry spices','1/2 onion','1 tsp oil']::text[], ARRAY['Fry the onion and spices, add tomatoes and simmer.','Add the paneer and warm through.','Serve with rice.']::text[], 'seed'),
('ares-cottage-cheese-pineapple', 'Cottage Cheese & Pineapple', 'Snack', 'A simple high-protein snack.', 250, 28, 20, 4, 1, 3, ARRAY['high-protein','quick','vegetarian','no-cook']::text[], ARRAY['200g low-fat cottage cheese','100g pineapple']::text[], ARRAY['Top the cottage cheese with pineapple.']::text[], 'seed'),
('ares-whey-shake-banana', 'Whey Shake & Banana', 'Snack', 'A fast around-training protein hit.', 300, 32, 35, 3, 1, 2, ARRAY['high-protein','quick','no-cook']::text[], ARRAY['1 scoop whey','300ml milk','1 banana']::text[], ARRAY['Shake the whey with milk and eat with a banana.']::text[], 'seed'),
('ares-yogurt-nuts', 'Greek Yoghurt & Mixed Nuts', 'Snack', 'Creamy yoghurt with a handful of nuts.', 260, 20, 12, 14, 1, 2, ARRAY['high-protein','quick','vegetarian','no-cook']::text[], ARRAY['150g Greek yoghurt','20g mixed nuts','1 tsp honey']::text[], ARRAY['Top the yoghurt with nuts and honey.']::text[], 'seed'),
('ares-apple-boiled-eggs', 'Apple & Boiled Eggs', 'Snack', 'A balanced grab-and-go snack.', 250, 14, 20, 12, 1, 10, ARRAY['quick','budget','no-cook']::text[], ARRAY['1 apple','2 boiled eggs']::text[], ARRAY['Boil the eggs ahead and pair with an apple.']::text[], 'seed'),
('ares-pb-banana-toast', 'Peanut Butter Banana Toast', 'Snack', 'Wholegrain toast with peanut butter and banana.', 380, 14, 48, 16, 1, 5, ARRAY['quick','vegetarian']::text[], ARRAY['1 slice wholegrain bread','1 tbsp peanut butter','1 banana']::text[], ARRAY['Toast the bread, spread the peanut butter and add sliced banana.']::text[], 'seed'),
('ares-protein-shake', 'Protein Shake', 'Snack', 'A lean protein top-up.', 160, 30, 6, 2, 1, 2, ARRAY['cutting','high-protein','quick','low-fat','no-cook']::text[], ARRAY['1.5 scoops whey','300ml water']::text[], ARRAY['Shake the whey with water.']::text[], 'seed'),
('ares-edamame-nuts', 'Edamame & Mixed Nuts', 'Snack', 'A plant-protein snack.', 250, 18, 14, 14, 1, 5, ARRAY['vegan','dairy-free','high-protein','no-cook']::text[], ARRAY['1 cup edamame','20g mixed nuts','Sea salt']::text[], ARRAY['Steam the edamame, salt lightly and serve with nuts.']::text[], 'seed'),
('ares-hummus-veg-crackers', 'Hummus, Veg & Crackers', 'Snack', 'Hummus with crunchy veg and wholegrain crackers.', 280, 12, 30, 12, 1, 5, ARRAY['vegetarian','high-fibre','no-cook']::text[], ARRAY['3 tbsp hummus','Carrot and cucumber sticks','4 wholegrain crackers']::text[], ARRAY['Serve the hummus with veg sticks and crackers.']::text[], 'seed'),
('ares-skyr-berries', 'Skyr with Berries', 'Snack', 'A low-fat, high-protein snack.', 200, 24, 18, 2, 1, 2, ARRAY['cutting','high-protein','low-fat','no-cook']::text[], ARRAY['170g skyr','100g berries']::text[], ARRAY['Top the skyr with berries.']::text[], 'seed')
